const LinterMessage = require('./message')
const { PROTECTED_NAMESPACES } = require('./config')

function _protectedNamespaceOf(name) {
  if (!name) return null
  return PROTECTED_NAMESPACES.find(ns => name === ns || name.startsWith(`${ns}.`)) ?? null
}

function locationString(element) {
  const loc = element?.$location
  if (!loc) return ''
  const line = loc.line ? `${loc.line}:` : ''
  return loc.col ? `${loc.file}:${line}${loc.col}:` : `${loc.file}:${line}`
}

// Rejects defining, extending or annotating artifacts in a protected namespace (e.g. 'cds.xt').
// Runs unconditionally, independent of linter configuration.
module.exports = class ProtectedNamespaceChecker {

  // eslint-disable-next-line no-unused-vars
  check(reflectedCsn, fullCsn, compileDir, mtxConfig) {
    const messages = []

    for (const name of Object.keys(reflectedCsn.definitions ?? {})) {
      if (_protectedNamespaceOf(name)) {
        messages.push(this._createWarning(name, reflectedCsn.definitions[name]))
      }
    }

    for (const extension of reflectedCsn.extensions ?? []) {
      const target = extension.extend ?? extension.annotate
      if (_protectedNamespaceOf(target)) {
        messages.push(this._createWarning(target, extension))
      }
    }

    return messages
  }

  _createWarning(name, element) {
    const namespace = _protectedNamespaceOf(name)
    const message = `Extending, annotating or defining '${name}' in the protected namespace '${namespace}' is not supported in extensions`
    return new LinterMessage(locationString(element) + message, element)
  }
}
